// ── W7 — the Tier-2 comprehension traversal rides THE ONE walk (L100 tail).
// These byte-pins were captured on the PRE-retirement emitter (post-#769) and
// prove the retirement moved nothing: clause rows in order, hint clauses as
// metadata-only rows (mid-stream AND trailing), source-before-expr, yield
// then the map-yield value. The full-corpus proof is the address-baseline
// gate (C9); these are the local drift guards.

fn pin_stream(def_source string, want string) {
	got := code.tier2_normalize_def(def_source) or {
		panic('normalize failed for `${def_source}`: ${err}')
	}
	assert got == want, 'Tier-2 stream moved (C9 — a moved hash is a defect):\n got: ${got}\nwant: ${want}'
}

