		'def:1p|(forsequencesequence|generator1:os(c12:store:source.2 0:\$b0 0:(Lstring_lit7://order))|generator1:ls\$r1:o/child4:line|binding1:re(Lcx_element1:*0:a0i2 \$r1:l/attr3:qty \$r1:l/attr5:price)|group_by0:e\$r1:o/child8:customer/attr6:region|y(Lcx_element3:row0:a2 6:region\$r3:key 7:revenue(c3:sum.1 0:\$r5:group/child1:r)i0))')
}

